#pragma once

#include <imgui.h>

#include "svg_icon_ids.hpp" // generated by CMake from src/assets/icons: enum class Icon

struct SDL_Renderer;

namespace trace {

// One embedded SVG file; the table is generated by CMake and indexed by `Icon` minus one.
struct SvgIconSource {
    const char* name; // file name without the extension
    const unsigned char* data;
    unsigned int size;
};
extern const SvgIconSource kSvgIconSources[];

// The icons are drawn from the SVG files in src/assets/icons, which are built into the program. Each icon is
// rasterized once per pixel size into a white-on-transparent texture and tinted with the color the caller gives,
// so one file serves the light and dark themes, the selected state on the accent, and the disabled look.
//
// Textures need the renderer: call initSvgIcons once it exists and releaseSvgIcons before it is destroyed. Without
// a renderer drawIcon draws nothing.
void initSvgIcons(SDL_Renderer* renderer);
void releaseSvgIcons() noexcept;

// Draws `icon` inside the square [min, min + size], rasterized at the exact pixel size so strokes stay sharp at any
// interface scale. `quarterTurns` rotates the icon clockwise in steps of 90 degrees (a horizontal "distribute" icon
// becomes the vertical one). Icon::None draws nothing.
void drawIcon(ImDrawList* dl, Icon icon, ImVec2 min, float size, ImU32 color, int quarterTurns = 0);

// The file name of an icon, for logs and tests; empty for Icon::None and out-of-range values.
const char* iconName(Icon icon) noexcept;

} // namespace trace
